  // ── Rules ──
  "rules.title": { en: "Rental Rules", fr: "Règles de location", ar: "قواعد الإيجار" },
  "rules.subtitle": { en: "General terms and conditions applicable to any reservation at CARFORFAR.", fr: "Les conditions générales applicables à toute réservation chez CarForFar.", ar: "الشروط والأحكام العامة المطبقة على أي حجز في كارفورفار." },
  "rules.km": { en: "Mileage", fr: "Kilométrage", ar: "عدد الكيلومترات" },
  "rules.km.desc": { en: "Each rental day includes 200 km. Beyond that, additional fees of 100 DH per day apply.", fr: "Chaque jour de location inclut 200 km. Au-delà, des frais supplémentaires de 100 DH par jour s'appliquent.", ar: "يشمل كل يوم إيجار 200 كم. بعد ذلك، يتم تطبيق رسوم إضافية قدرها 100 درهم يوميًا." },
  "rules.km.detail": { en: "3 days = 600 km included. If you drive 800 km, the extra 200 km will be charged 100 DH.", fr: "3 jours = 600 km inclus. Si vous parcourez 800 km, les 200 km supplémentaires vous seront facturés 100 DH.", ar: "3 أيام = 600 كم مشمولة. إذا قطعت 800 كم، فسيتم تحصيل 100 درهم عن الـ 200 كم الإضافية." },
  "rules.insurance": { en: "Insurance & Deposit", fr: "Assurance & Caution", ar: "التأمين والضمان" },
  "rules.insurance.desc": { en: "A deposit of 5,000 DH is required upon vehicle delivery. Basic insurance is included.", fr: "Une caution de 5 000 DH est requise à la remise du véhicule. L'assurance de base est incluse.", ar: "مطلوب وديعة تأمين قدرها 5000 درهم عند تسليم المركبة. التأمين الأساسي مشمول." },
  "rules.insurance.detail": { en: "The deposit is fully refunded upon vehicle return if no damage is noted.", fr: "La caution vous est restituée intégralement à la restitution du véhicule si aucun dommage n'est constaté.", ar: "يتم استرداد الوديعة بالكامل عند إعادة المركبة إذا لم يتم ملاحظة أي ضرر." },
  "rules.age": { en: "Age Requirements", fr: "Conditions d'âge", ar: "شروط العمر" },
  "rules.age.desc": { en: "The driver must be at least 21 years old and have held a driver's license for more than one year.", fr: "Le conducteur doit être âgé d'au moins 21 ans et titulaire du permis de conduire depuis plus d'un an.", ar: "يجب أن يكون عمر السائق 21 عامًا على الأقل وأن يكون حاصلاً على رخصة القيادة لأكثر من عام." },
  "rules.age.detail": { en: "Drivers under 25 may be subject to a young driver surcharge.", fr: "Les conducteurs de moins de 25 ans peuvent être soumis à une surprime jeune conducteur.", ar: "قد يخضع السائقون الذين تقل أعمارهم عن 25 عامًا لرسوم إضافية." },
  "rules.duration": { en: "Rental Duration", fr: "Durée de location", ar: "مدة الإيجار" },
  "rules.duration.desc": { en: "Rental is by the day. The vehicle must be returned before 6 PM on the return date.", fr: "La location se fait à la journée. La restitution du véhicule doit se faire avant 18h le jour de retour.", ar: "الإيجار يومي. يجب إعادة المركبة قبل الساعة 6 مساءً في تاريخ الإرجاع." },
  "rules.duration.detail": { en: "Any hourly delay will be charged 50 DH per additional hour started.", fr: "Tout dépassement horaire sera facturé 50 DH par heure supplémentaire entamée.", ar: "سيتم تحصيل 50 درهمًا عن كل ساعة تأخير إضافية." },
  "rules.documents": { en: "Required Documents", fr: "Documents requis", ar: "المستندات المطلوبة" },
  "rules.documents.desc": { en: "A valid ID (CIN) and driver's license are mandatory.", fr: "Une pièce d'identité (CIN) et le permis de conduire en cours de validité sont obligatoires.", ar: "بطاقة الهوية (CIN) ورخصة القيادة سارية المفعول إلزامية." },
  "rules.documents.detail": { en: "Documents must be uploaded in your profile before reservation confirmation.", fr: "Les documents doivent être téléchargés dans votre profil avant la confirmation de la réservation.", ar: "يجب تحميل المستندات في ملفك الشخصي قبل تأكيد الحجز." },

