  "privacy.s2_item_2_detail_3": { en: "Booking history", fr: "Historique des réservations", ar: "سجل الحجوزات" },
  "privacy.s2_item_3_sub": { en: "Supporting Documents", fr: "Documents justificatifs", ar: "المستندات الداعمة" },
  "privacy.s2_item_3_detail_1": { en: "National ID Card (CIN)", fr: "Carte Nationale d'Identité (CNI/CIN)", ar: "البطاقة الوطنية للتعريف (CIN)" },
  "privacy.s2_item_3_detail_2": { en: "Driver's license", fr: "Permis de conduire", ar: "رخصة القيادة" },
  "privacy.s2_item_4_sub": { en: "Technical Data", fr: "Données techniques", ar: "البيانات التقنية" },
  "privacy.s2_item_4_detail_1": { en: "IP address", fr: "Adresse IP", ar: "عنوان IP" },
  "privacy.s2_item_4_detail_2": { en: "Browser type", fr: "Type de navigateur", ar: "نوع المتصفح" },
  "privacy.s2_item_4_detail_3": { en: "Operating system", fr: "Système d'exploitation", ar: "نظام التشغيل" },
  "privacy.s2_item_4_detail_4": { en: "Browsing data on the site", fr: "Données de navigation sur le site", ar: "بيانات التصفح على الموقع" },
  "privacy.s3_title": { en: "Purposes of Collection", fr: "Finalités de la collecte", ar: "أغراض الجمع" },
  "privacy.s3_content": { en: "The collected data is used to:", fr: "Les données collectées sont utilisées pour :", ar: "يتم استخدام البيانات التي تم جمعها من أجل:" },
  "privacy.s3_list_1": { en: "Manage vehicle reservations", fr: "Gérer les réservations de véhicules", ar: "إدارة حجوزات المركبات" },
  "privacy.s3_list_2": { en: "Verify customer identity", fr: "Vérifier l'identité des clients", ar: "التحقق من هوية العملاء" },
  "privacy.s3_list_3": { en: "Ensure rental follow-up", fr: "Assurer le suivi des locations", ar: "ضمان متابعة الإيجارات" },
  "privacy.s3_list_4": { en: "Respond to user requests", fr: "Répondre aux demandes des utilisateurs", ar: "الرد على استفسارات المستخدمين" },
  "privacy.s3_list_5": { en: "Improve our services", fr: "Améliorer nos services", ar: "تحسين خدماتنا" },
  "privacy.s3_list_6": { en: "Guarantee platform security", fr: "Garantir la sécurité de la plateforme", ar: "ضمان أمان المنصة" },
  "privacy.s3_list_7": { en: "Comply with legal obligations", fr: "Respecter nos obligations légales", ar: "الامتثال لالتزاماتنا القانونية" },
  "privacy.s4_title": { en: "Data Retention", fr: "Conservation des données", ar: "الاحتفاظ بالبيانات" },
  "privacy.s4_content": { en: "Personal data is retained only for the duration necessary for the purposes for which it was collected or in accordance with applicable legal obligations.", fr: "Les données personnelles sont conservées uniquement pendant la durée nécessaire aux finalités pour lesquelles elles ont été collectées ou conformément aux obligations légales applicables.", ar: "يتم الاحتفاظ بالبيانات الشخصية فقط للمدة اللازمة للأغراض التي تم جمعها من أجلها أو وفقًا للالتزامات القانونية المعمول بها." },
  "privacy.s5_title": { en: "Data Sharing", fr: "Partage des données", ar: "مشاركة البيانات" },
  "privacy.s5_content": { en: "Carforfar does not sell or rent its users' personal data.\n\nData may only be disclosed to:", fr: "Carforfar ne vend ni ne loue les données personnelles de ses utilisateurs.\n\nLes données peuvent être communiquées uniquement :", ar: "لا تبيع Carforfar أو تؤجر البيانات الشخصية لمستخدميها.\n\nلا يمكن الإفصاح عن البيانات إلا إلى:" },
  "privacy.s5_list_1": { en: "Authorized employees of the company", fr: "Aux employés autorisés de l'entreprise", ar: "الموظفين المصرح لهم في الشركة" },
  "privacy.s5_list_2": { en: "Technical service providers necessary for service operation", fr: "Aux prestataires techniques nécessaires au fonctionnement du service", ar: "مقدمي الخدمات الفنية اللازمين لتشغيل الخدمة" },
  "privacy.s5_list_3": { en: "Competent authorities when required by law", fr: "Aux autorités compétentes lorsque la loi l'exige", ar: "السلطات المختصة عندما يقتضي القانون ذلك" },
  "privacy.s6_title": { en: "Data Security", fr: "Sécurité des données", ar: "أمان البيانات" },
  "privacy.s6_content": { en: "We implement appropriate technical and organizational measures to protect your data against unauthorized access, loss, alteration, or disclosure.", fr: "Nous mettons en œuvre des mesures techniques et organisationnelles appropriées afin de protéger vos données contre tout accès non autorisé, perte, altération ou divulgation.", ar: "ننفذ تدابير تقنية وتنظيمية مناسبة لحماية بياناتك من الوصول غير المصرح به أو الفقدان أو التغيير أو الإفصاح." },
  "privacy.s7_title": { en: "Cookies", fr: "Cookies", ar: "ملفات تعريف الارتباط" },
  "privacy.s7_content": { en: "Our site may use cookies to:", fr: "Notre site peut utiliser des cookies afin :", ar: "قد يستخدم موقعنا ملفات تعريف الارتباط من أجل:" },
  "privacy.s7_list_1": { en: "Improve user experience", fr: "D'améliorer l'expérience utilisateur", ar: "تحسين تجربة المستخدم" },
  "privacy.s7_list_2": { en: "Analyze site traffic", fr: "D'analyser le trafic du site", ar: "تحليل حركة المرور على الموقع" },
  "privacy.s7_list_3": { en: "Remember certain browsing preferences", fr: "De mémoriser certaines préférences de navigation", ar: "تذكر بعض تفضيلات التصفح" },
  "privacy.s7_after": { en: "Users can configure their browser to refuse cookies.", fr: "L'utilisateur peut configurer son navigateur pour refuser les cookies.", ar: "يمكن للمستخدم تكوين متصفحه لرفض ملفات تعريف الارتباط." },
  "privacy.s8_title": { en: "User Rights", fr: "Droits des utilisateurs", ar: "حقوق المستخدمين" },
  "privacy.s8_content": { en: "Under applicable regulations, you have the following rights:", fr: "Conformément à la réglementation applicable, vous disposez des droits suivants :", ar: "وفقًا للوائح المعمول بها، لديك الحقوق التالية:" },
  "privacy.s8_list_1": { en: "Right to access your data", fr: "Droit d'accès à vos données", ar: "حق الوصول إلى بياناتك" },
  "privacy.s8_list_2": { en: "Right to rectification", fr: "Droit de rectification", ar: "حق التصحيح" },
  "privacy.s8_list_3": { en: "Right to erasure", fr: "Droit de suppression", ar: "حق الحذف" },
  "privacy.s8_list_4": { en: "Right to object to processing", fr: "Droit d'opposition au traitement", ar: "حق الاعتراض على المعالجة" },
