export function t(key: string, locale: Locale, vars?: Record<string, string>): string {
  const entry = labels[key];
  if (!entry) return key;
  let text = entry[locale];
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      text = text.replace(`{${k}}`, v);
    }
  }
  return text;
}
